import { useDispatch } from 'react-redux';

import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterStatus,
} from 'hooks';
import type { FilterDataStructure, FilterForm } from 'models/Filters';
import { AppDispatch } from 'redux/types';

import { FILTER_CONFIGS } from '../../../constants';

interface UsePosToolFiltersReturn {
  applied: FilterForm;
  isGlobalZone: boolean;
  dataFilters: FilterDataStructure;
  defaults: FilterForm;
  isLoaded: boolean;
  isError: boolean;
  dispatch: AppDispatch;
}

export function usePosToolFilters(): UsePosToolFiltersReturn {
  const dispatch = useDispatch<AppDispatch>();
  const { applied, isGlobalZone } = usePageFilterApplied(
    FILTER_CONFIGS.pageName,
  );
  const { dataFilters, defaults } = usePageFilterData(FILTER_CONFIGS.pageName);
  const { isLoaded, isError } = usePageFilterStatus(FILTER_CONFIGS.pageName);

  return {
    applied,
    isGlobalZone,
    dataFilters,
    defaults,
    isLoaded,
    isError,
    dispatch,
  };
}
